export class PubSubCoordinator {
  constructor() {
    this.subscribers = new Map();
  }

  subscribe(eventType, callback) {
    if (!this.subscribers.has(eventType)) {
      this.subscribers.set(eventType, []);
    }
    this.subscribers.get(eventType).push(callback);
  }

  publish(eventType, data) {
    if (this.subscribers.has(eventType)) {
      this.subscribers.get(eventType).forEach(callback => callback(data));
    }
  }

  delegateTask(eventType, task) {
    // Example bounded autonomy logic
    const priority = task.priority || 'normal';
    this.publish(eventType, { task, priority });
  }
}

export const pubSubLayer = new PubSubCoordinator();